    # Identify all rooms and fill their bounding boxes
    visited = [[False]*m for _ in range(n)]
    rooms = []

    for r in range(n):
        for c in range(m):
            if not visited[r][c] and grid[r][c] == '.':
                room = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    room.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == '.':
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                rooms.append(room)

    # Helper to check if cells form rectangle
    def is_rect(cells):
        if not cells: return True
        rows = set(r for r,c in cells)
        cols = set(c for r,c in cells)
        return len(rows) * len(cols) == len(cells)

    # Fill gaps in non-rectangular rooms
    for room in rooms:
        if not is_rect(room):
            min_r, max_r = min(r for r,c in room), max(r for r,c in room)
            min_c, max_c = min(c for r,c in room), max(c for r,c in room)
            for r in range(min_r, max_r+1):
                for c in range(min_c, max_c+1):
                    if grid[r][c] == '*':
                        grid[r][c] = '.'

