    results = []
    idx = 0

    while idx < len(lines):
        if not lines[idx].strip():
            idx += 1
            continue

        q = int(lines[idx])
        idx += 1

        for _ in range(q):
            n = int(lines[idx])
            idx += 1
            a = list(map(int, lines[idx].split()))
            idx += 1

            if n == 1:
                results.append('0')
                continue

            # Get distinct sorted values
            distinct = sorted(set(a))

            # Count positions of each distinct value
            val_pos = {}
            for v in distinct:
                positions = []
                for i, x in enumerate(a):
                    if x == v:
                        positions.append(i)
                val_pos[v] = positions

            # Find longest consecutive subsequence where each value appears before next
            max_len = 1
            current_len = 1

            for i in range(1, len(distinct)):
                v1, v2 = distinct[i-1], distinct[i]
                # All occurrences of v1 must appear before all occurrences of v2
                if val_pos[v2][0] > val_pos[v1][-1]:
                    current_len += 1
                else:
                    max_len = max(max_len, current_len)
                    current_len = 1

            max_len = max(max_len, current_len)
            results.append(str(len(distinct) - max_len))

    return '\n'.join(results)

