        remove_cost = m * a_cost

        # Remaining elements must be valid (not inf)
        # We want to find the minimum cost over all valid segment removals
        # That is, min(prefix + suffix where segment m is removed)

        valid = True
        prefix = [0] * n
        for i in range(n):
