                prefix[i] = prefix[i-1] if i > 0 else 0
            else:
                valid = False
                prefix[i] = float('inf')

        if not valid:
            continue

        # For each end position of segment to remove, check min prefix cost
        # We remove elements [i, i+m-1], keeping [0, i-1] and [i+m, n-1]
        for i in range(n - m):
            # Remove elements from index i to i+m-1
            prefix_sum = prefix[i-1] if i > 0 else 0
            suffix_sum = 0
            for j in range(i+m, n):
                if mod_costs[j] == float('inf'):
                    valid = False
                    break
                suffix_sum += mod_costs[j]
            if valid:
                cost = prefix_sum + suffix_sum + remove_cost
                min_cost = min(min_cost, cost)

