        return "0\n"
    if x == 0:
        # gcd(0, y) = y, so we subtract y once
        return "1\n"

    # Efficient computation of f(x, y)
    steps = 0
    current_y = y

    while current_y > 0:
        g = gcd(x, current_y)
        # We need to subtract g until current_y changes or becomes 0
        # gcd(x, current_y) = gcd(x, current_y - k*g)
        # We can subtract g multiple times
        # How many times? Until current_y becomes a multiple of something different

        # Actually, current_y -= g doesn't change gcd(x, current_y) significantly
        # But when current_y reaches 0 or changes divisibility properties, it does change

        # Simple approach: we subtract g. If gcd(x, current_y - g) != g,
        # then the next step will use a different divisor
        # But actually, gcd(x, y) divides both x and y, so gcd(x, y-mod) = gcd(x, mod)
        # Where mod = y % gcd(x, y) when we only subtract gcd(x, y) multiple times

        # Let me think differently:
        # If gcd(x, y) = g, then gcd(x, y - g) = gcd(x, y) = g as long as y is not reduced to 0
        # Wait, gcd(a, b - g) where g = gcd(a, b).
        # gcd(a, b - g) = gcd(a, b) = g if b is a multiple of g... but b IS a multiple of g
        # So gcd(a, b - g) = g!
        # Therefore we keep subtracting the same g until b < g (but we stop at 0)
        # So steps = y // g

        steps += current_y // g
        current_y %= g

    return f"{steps}\n"


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

