def solution(data):
    """
    Count the number of binary codes of length n that satisfy all m attempt constraints.
    Each attempt specifies which positions should match.
    Uses meet-in-the-middle for large n to handle up to n=35.
    """
    # Set recursion limit for deep recursion if needed
    sys.setrecursionlimit(100000)

    lines = data.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        attempt_str = parts[0]
        expected = int(parts[1])
        # Convert binary string to list of integers
        attempt_bits = [int(b) for b in attempt_str]
        attempts.append((attempt_bits, expected))

    if m == 0:
        return str(1 << n)

    # Use meet-in-the-middle for efficiency when n is large
    if n > 20:
        half = n // 2

        first_half_matches = {}  # mask -> (matches for each attempt in first half)

        for mask in range(1 << half):
            matches = [0] * m
            for attempt, _ in attempts:
                for j in range(half):
                    if (mask >> j) & 1 == attempt[j]:
                        matches[j] += 1
            first_half_matches[mask] = tuple(matches)

        # For second half, we need to find masks where
        # first_half_mask + second_half_mask matches = expected for each attempt
        result = 0

        for mask in range(1 << (n - half)):
            matches2 = [0] * m
            for attempt, _ in attempts:
                for j in range(n - half):
                    if (mask >> j) & 1 == attempt[half + j]:
                        matches2[j] += 1

            # Check if any first half can complement this second half
            for _, matches1 in first_half_matches.items():
                # Check if combining matches would satisfy all attempts
                all_satisfied = True
                for j in range(m):
                    if matches1[j] + matches2[j] != attempts[j][1]:
                        all_satisfied = False
                        break

                if all_satisfied:
                    result += 1

    else:
        # For smaller n, brute force all 2^n codes
        for mask in range(1 << n):
            code = [(mask >> i) & 1 for i in range(n)]
            valid = True
            for attempt_bits, expected in attempts:
                match_count = sum(1 for j in range(n) if code[j] == attempt_bits[j])
                if match_count != expected:
                    valid = False
                    break
            if valid:
                result += 1

    return str(result)


